solution.solution.c:
#include <string.h>

int max_int(int a, int b) { return a > b ? a : b; }
double max_double(double a, double b) { return a > b ? a : b; }
const char *max_string(const char *a, const char *b) { return strcmp(a, b) > 0 ? a : b; }

#define max(a, b) _Generic((a), int: max_int, double: max_double, char *: max_string, const char *: max_string)((a), (b))

unitTests:
TEST("ints") { CHECK_EQ(max(3, 9), 9); CHECK_EQ(max(-3, -9), -3); }
TEST("doubles") { CHECK_NEAR(max(2.5, -1.0), 2.5, 1e-12); CHECK_NEAR(max(0.1, 0.2), 0.2, 1e-12); }
TEST("strings") { CHECK_STR(max("pear", "apple"), "pear"); const char *a = "fig"; const char *b = "kiwi"; CHECK_STR(max(a, b), "kiwi"); }

